      + '<span class="sv-hint">' + svPlural(svByName(list).length, 'sleeve') + (list.length > svByName(list).length ? ' and ' + svPlural(list.length - svByName(list).length, 'edition') : '')
      + ' under ' + esc(repo.variant) + '</span>'
